352: static js_value_t *
353: bare_os_network_interfaces(js_env_t *env, js_callback_info_t *info) {
354:   int err;
355: 
356:   uv_interface_address_t *addresses;
357:   int len;
358:   err = uv_interface_addresses(&addresses, &len);
359:   if (err < 0) {
360:     err = js_throw_error(env, uv_err_name(err), uv_strerror(err));
361:     assert(err == 0);
362: 
363:     return NULL;
364:   }
365: 
366:   js_value_t *result;
367:   err = js_create_array_with_length(env, len, &result);
368:   assert(err == 0);
369: 
370:   for (size_t i = 0, n = len; i < n; i++) {
371:     uv_interface_address_t address = addresses[i];
372: 
373:     uint32_t family = address.address.address4.sin_family;
374: 
375:     if (family != AF_INET && family != AF_INET6) {
376:       continue;
377:     }
378: 
379:     js_value_t *item;
380:     err = js_create_object(env, &item);
381:     assert(err == 0);
382: 
383:     js_value_t *val;
384: 
385:     err = js_create_string_utf8(env, (utf8_t *) address.name, -1, &val);
386:     assert(err == 0);
387: 
388:     err = js_set_named_property(env, item, "name", val);
389:     assert(err == 0);
390: 
391:     char address_ip[INET6_ADDRSTRLEN];
392:     char netmask_ip[INET6_ADDRSTRLEN];
393:     char family_string[5];
394: 
395:     char cidr[INET6_ADDRSTRLEN + 8];
396:     uint32_t cidr_value = 0;
397: 
398:     if (family == AF_INET) {
399:       err = uv_ip4_name(&address.address.address4, address_ip, sizeof(address_ip));
400:       assert(err == 0);
401: 
402:       err = uv_ip4_name(&address.netmask.netmask4, netmask_ip, sizeof(netmask_ip));
403:       assert(err == 0);
404: 
405:       strcpy(family_string, "IPv4");
406: 
407:       cidr_value = bare_os__population_count(address.netmask.netmask4.sin_addr.s_addr);
408:     } else {
409:       err = uv_ip6_name(&address.address.address6, address_ip, sizeof(address_ip));
410:       assert(err == 0);
411: 
412:       err = uv_ip6_name(&address.netmask.netmask6, netmask_ip, sizeof(netmask_ip));
413:       assert(err == 0);
414: 
415:       strcpy(family_string, "IPv6");
416: 
417:       for (size_t i = 0; i < 16; i++) {
418:         uint32_t count = bare_os__population_count(address.netmask.netmask6.sin6_addr.s6_addr[i]);
419: 
420:         if (count == 0) break;
421: 
422:         cidr_value += count;
423:       }
424:     }
425: 
426:     err = js_create_string_utf8(env, (utf8_t *) address_ip, -1, &val);
427:     assert(err == 0);
428: 
429:     err = js_set_named_property(env, item, "address", val);
430:     assert(err == 0);
431: 
432:     err = js_create_string_utf8(env, (utf8_t *) netmask_ip, -1, &val);
433:     assert(err == 0);
434: 
435:     err = js_set_named_property(env, item, "netmask", val);
436:     assert(err == 0);
437: 
438:     err = js_create_string_utf8(env, (utf8_t *) family_string, -1, &val);
439:     assert(err == 0);
440: 
441:     err = js_set_named_property(env, item, "family", val);
442:     assert(err == 0);
443: 
444:     err = snprintf(cidr, sizeof(cidr), "%s/%d", address_ip, cidr_value);
445:     assert(err > 0);
446: 
447:     err = js_create_string_utf8(env, (utf8_t *) cidr, -1, &val);
448:     assert(err == 0);
449: 
450:     err = js_set_named_property(env, item, "cidr", val);
451:     assert(err == 0);
452: 
453:     char mac[18];
454:     err = snprintf(
455:       mac,
456:       sizeof(mac),
457:       "%02x:%02x:%02x:%02x:%02x:%02x",
458:       (unsigned char) address.phys_addr[0],
459:       (unsigned char) address.phys_addr[1],
460:       (unsigned char) address.phys_addr[2],
461:       (unsigned char) address.phys_addr[3],
462:       (unsigned char) address.phys_addr[4],
463:       (unsigned char) address.phys_addr[5]
464:     );
465:     assert(err > 0);
466: 
467:     err = js_create_string_utf8(env, (utf8_t *) mac, -1, &val);
468:     assert(err == 0);
469: 
470:     err = js_set_named_property(env, item, "mac", val);
471:     assert(err == 0);
472: 
473:     err = js_get_boolean(env, address.is_internal == 1, &val);
474:     assert(err == 0);
475: 
476:     err = js_set_named_property(env, item, "internal", val);
477:     assert(err == 0);
478: 
479:     if (family == AF_INET6) {
480:       err = js_create_uint32(env, address.address.address6.sin6_scope_id, &val);
481:       assert(err == 0);
482: 
483:       err = js_set_named_property(env, item, "scopeid", val);
484:       assert(err == 0);
485:     }
486: 
487:     err = js_set_element(env, result, i, item);
488:     assert(err == 0);
489:   }
490: 
491:   uv_free_interface_addresses(addresses, len);
492: 
493:   return result;
494: }
